package com.primehr.performancemanagement.api;
import com.primehr.performancemanagement.api.PerformanceManagementDtos.*;import com.primehr.performancemanagement.application.*;import com.primehr.security.*;import com.primehr.shared.api.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/primehr/v1/performance-management")public class PerformanceManagementController{private final PerformancePolicyService policies;private final PerformanceCycleService cycles;private final PerformancePolicyPermissionGuard policyPermission;private final PerformanceCyclePermissionGuard cyclePermission;private final AgencyScopeResolver agency;
 public PerformanceManagementController(PerformancePolicyService p,PerformanceCycleService c,PerformancePolicyPermissionGuard pp,PerformanceCyclePermissionGuard cp,AgencyScopeResolver a){policies=p;cycles=c;policyPermission=pp;cyclePermission=cp;agency=a;}
 @GetMapping("/policies")public List<PolicyResponse>policies(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){policyPermission.require(PrimeHrAction.ACCESS,t);return policies.list(agency.resolveAgencyId(a));}@GetMapping("/policies/{id}")public PolicyResponse policy(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){policyPermission.require(PrimeHrAction.ACCESS,t);return policies.get(agency.resolveAgencyId(a),id);}@GetMapping("/policies/effective")public PolicyResponse effective(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam LocalDate on){policyPermission.require(PrimeHrAction.ACCESS,t);return policies.effective(agency.resolveAgencyId(a),on);}
 @PostMapping("/policies")@ResponseStatus(HttpStatus.CREATED)public PolicyResponse createPolicy(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody PolicyInput r){policyPermission.require(PrimeHrAction.ADD,t);return policies.create(agency.resolveAgencyId(a),r,c);}@PutMapping("/policies/{id}")public PolicyResponse updatePolicy(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody PolicyInput r){policyPermission.require(PrimeHrAction.EDIT,t);return policies.update(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/policies/{id}/publish")public PolicyResponse publish(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody PolicyTransition r){policyPermission.require(PrimeHrAction.PUBLISH,t);return policies.publish(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/policies/{id}/revisions")@ResponseStatus(HttpStatus.CREATED)public PolicyResponse revision(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionTransition r){policyPermission.require(PrimeHrAction.ADD,t);return policies.revision(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/policies/{id}/retire")public PolicyResponse retire(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionTransition r){policyPermission.require(PrimeHrAction.PUBLISH,t);return policies.retire(agency.resolveAgencyId(a),id,r,c);}
 @GetMapping("/cycles")public PageResponse<CycleResponse>cycles(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){cyclePermission.require(PrimeHrAction.ACCESS,t);return cycles.list(agency.resolveAgencyId(a),page,size);}@GetMapping("/cycles/{id}")public CycleResponse cycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){cyclePermission.require(PrimeHrAction.ACCESS,t);return cycles.get(agency.resolveAgencyId(a),id);}@PostMapping("/cycles")@ResponseStatus(HttpStatus.CREATED)public CycleResponse createCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody CycleInput r){cyclePermission.require(PrimeHrAction.ADD,t);return cycles.create(agency.resolveAgencyId(a),r,c);}@PutMapping("/cycles/{id}")public CycleResponse updateCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CycleInput r){cyclePermission.require(PrimeHrAction.EDIT,t);return cycles.update(agency.resolveAgencyId(a),id,r,c);}@PutMapping("/cycles/{id}/milestones")public CycleResponse milestones(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody MilestonesInput r){cyclePermission.require(PrimeHrAction.EDIT,t);return cycles.milestones(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/cycles/{id}/open")public CycleResponse open(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CycleTransition r){cyclePermission.require(PrimeHrAction.FINALIZE,t);return cycles.open(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/cycles/{id}/close")public CycleResponse close(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CycleTransition r){cyclePermission.require(PrimeHrAction.FINALIZE,t);return cycles.close(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/cycles/{id}/cancel")public CycleResponse cancel(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CycleTransition r){cyclePermission.require(PrimeHrAction.FINALIZE,t);return cycles.cancel(agency.resolveAgencyId(a),id,r,c);}
}
